{"date":"2025-01-01","company":"Magic Wavelength Pty Ltd","company_geography":"australia","direction":"Real-time data-driven drone agrochemical sprayer","business_model":"B2B / agtech / hardware","round":"Innovation Booster Grant","amount_text":"A$50k","amount_value":50000,"amount_currency":"AUD","role":"Grant provider","investor_evidence_url":"https://www.wa.gov.au/organisation/department-of-energy-and-economic-diversification/innovation-booster-grant-2025-recipients"},{"date":"2025-01-01","company":"Velora Health","company_geography":"australia","direction":"Novel device to objectively measure infant breastmilk intake","business_model":"B2C / health hardware","round":"Innovation Booster Grant","amount_text":"A$50k","amount_value":50000,"amount_currency":"AUD","role":"Grant provider","investor_evidence_url":"https://www.wa.gov.au/organisation/department-of-energy-and-economic-diversification/innovation-booster-grant-2025-recipients"}]$json$::jsonb,
