  entity_type,
  entity_id,
  section_key,
  chunk_text,
  source_urls,
  metadata,
  confidence,
  review_needed,
  rag_allowed
)
SELECT
  id,
  slug,
  'investor',
  'fund:' || slug,
  'matching_profile',
  format(
    '%s investor profile. Stage focus: %s. Sector focus: %s. Geography focus: %s. Business model focus: %s. Cheque ranges: %s. Lead behavior: %s. AI appetite: %s. Notes: %s',
    name,
    array_to_string(stage_focus, ', '),
    array_to_string(sector_focus, ', '),
    array_to_string(geography_focus, ', '),
    array_to_string(business_model_focus, ', '),
    cheque_ranges::text,
    lead_behavior,
    ai_appetite,
    coalesce(screening_notes, '')
  ),
  ARRAY[]::text[],
  jsonb_build_object(
    'source', 'seed.investors',
    'stage_focus', stage_focus,
    'sector_focus', sector_focus,
    'geography_focus', geography_focus,
    'business_model_focus', business_model_focus
  ),
  'medium',
  false,
  true
FROM investors
WHERE slug IN ('airtree', 'antler-australia', 'archangel-ventures', 'aura-ventures', 'black-nova-vc', 'blackbird', 'brisbane-angels', 'climate-tech-partners', 'enterprize-elevate', 'evp', 'flying-fox-ventures', 'folklore-ventures', 'galileo-ventures', 'investible', 'jelix-ventures', 'm8-ventures', 'macdoch-ventures', 'main-sequence', 'melbourne-angels', 'rampersand', 'significant-ventures', 'skalata-ventures', 'southern-angels', 'spacecubed-ventures-plus-eight', 'square-peg', 'startmate', 'sydney-angels', 'tidal-ventures', 'virescent-ventures', 'perth-angels', 'capital-angels', 'hunter-angels', 'australian-medical-angels', 'aussie-angels', 'ten13', 'overnight-success-syndicate', 'euphemia-syndicate', 'cmack-ventures', 'scale-venture-fund-i', 'alice-anderson-fund', 'tractor-ventures', 'qld-business-development-fund-bdf', 'advance-queensland-ignite-ideas', 'breakthrough-victoria', 'south-australian-venture-capital-fund-savcf', 'wa-new-industries-fund', 'activate-capital', 'industry-growth-program-federal', 'monash-ventures-pre-seed-fund');

INSERT INTO rag_chunks (
  investor_id,
  investor_slug,
  entity_type,
  entity_id,
  section_key,
  chunk_text,
  source_urls,
  metadata,
  confidence,
  review_needed,
  rag_allowed
)
SELECT
  i.id,
  i.slug,
  'deal',
  i.slug || ':' || ordinality::text || ':' ||
    lower(regexp_replace(coalesce(deal->>'company', 'deal'), '[^a-zA-Z0-9]+', '-', 'g')),
  'recent_deal',
  format(
    '%s recent deal evidence. Company: %s. Round: %s. Amount: %s. Geography: %s. Direction: %s. Business model: %s. Role: %s. Date: %s.',
    i.name,
    coalesce(deal->>'company', 'unknown'),
    coalesce(deal->>'round', 'unknown'),
    coalesce(deal->>'amount_text', deal->>'amount', 'unknown'),
    coalesce(deal->>'company_geography', deal->>'region', 'unknown'),
    coalesce(deal->>'direction', 'unknown'),
    coalesce(deal->>'business_model', 'unknown'),
    coalesce(deal->>'role', 'unknown'),
    coalesce(deal->>'date', 'unknown')
  ),
  array_remove(ARRAY[deal->>'investor_evidence_url'], NULL),
  jsonb_build_object(
    'source', 'seed.recent_deals',
    'company', deal->>'company',
    'round', deal->>'round',
    'amount_text', coalesce(deal->>'amount_text', deal->>'amount'),
    'company_geography', coalesce(deal->>'company_geography', deal->>'region'),
    'business_model', deal->>'business_model',
    'role', deal->>'role',
    'date', deal->>'date'
  ),
  'medium',
  false,
  true
FROM investors i
CROSS JOIN LATERAL jsonb_array_elements(i.recent_deals)
WITH ORDINALITY AS deal_rows(deal, ordinality)
WHERE i.slug IN ('airtree', 'antler-australia', 'archangel-ventures', 'aura-ventures', 'black-nova-vc', 'blackbird', 'brisbane-angels', 'climate-tech-partners', 'enterprize-elevate', 'evp', 'flying-fox-ventures', 'folklore-ventures', 'galileo-ventures', 'investible', 'jelix-ventures', 'm8-ventures', 'macdoch-ventures', 'main-sequence', 'melbourne-angels', 'rampersand', 'significant-ventures', 'skalata-ventures', 'southern-angels', 'spacecubed-ventures-plus-eight', 'square-peg', 'startmate', 'sydney-angels', 'tidal-ventures', 'virescent-ventures', 'perth-angels', 'capital-angels', 'hunter-angels', 'australian-medical-angels', 'aussie-angels', 'ten13', 'overnight-success-syndicate', 'euphemia-syndicate', 'cmack-ventures', 'scale-venture-fund-i', 'alice-anderson-fund', 'tractor-ventures', 'qld-business-development-fund-bdf', 'advance-queensland-ignite-ideas', 'breakthrough-victoria', 'south-australian-venture-capital-fund-savcf', 'wa-new-industries-fund', 'activate-capital', 'industry-growth-program-federal', 'monash-ventures-pre-seed-fund');

